"""Opt-in offline recall/latency evaluation using a prepared local model.

Run: python tests/eval_harness_recall.py --output /tmp/recall-results.json
Uses synthetic lessons in a disposable database; never downloads a model.
"""
import argparse
import json
import os
from pathlib import Path
import statistics
import sys
import tempfile
import time
from unittest.mock import patch

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from lib import harness, semantic_memory as semantic

# Fixed cases, not generated by or adjusted by the embedding model.
CASES = [
    ("When explaining Python recursion", "Use a countdown example and show the base case that stops repeated calls.",
     "Demonstrate a function calling itself until a stopping condition is reached."),
    ("When planning vegetarian meals", "Suggest filling dishes made without meat or fish.",
     "What could I cook for dinner without any animal flesh?"),
    ("Before deleting local files", "Show the affected paths and ask for confirmation before removing them.",
     "Erase the old documents from my laptop."),
    ("When explaining database storage", "Use a small customer table as the example and keep the explanation concrete.",
     "How does a relational system persist records on disk?"),
    ("When choosing the length of answers", "Keep responses concise and avoid unnecessary detail.",
     "Give me the short version, please."),
    ("When explaining difficult programming concepts", "Start with a simple analogy before introducing technical terminology.",
     "Teach me a complicated coding idea as if I am a beginner."),
    ("When checking tomorrow's weather forecast", "Look up the next day's forecast rather than reporting current conditions.",
     "Will it rain the day after today?"),
    ("When finding duplicate photographs", "Compare image content before suggesting which copies to remove.",
     "Help me locate repeated pictures in my collection."),
    ("When scheduling study sessions", "Include breaks and time to revise previously studied material.",
     "Make a timetable for learning and revision."),
    ("When managing account passwords", "Recommend unique credentials stored in a reputable password manager.",
     "How should I organize my login secrets securely?"),
    ("When backing up important documents", "Keep a separate recoverable copy and verify restoration works.",
     "Protect my files so I can recover them if the drive fails."),
    ("When explaining computer memory usage", "Distinguish RAM in use from storage occupied on disk.",
     "Why is my machine running out of RAM even though the drive has free space?"),
]
DISTRACTORS = ["guitar tuning", "sourdough baking", "bicycle brakes", "bird identification",
    "chess openings", "indoor plant watering", "running shoes", "tea brewing",
    "camping tents", "knitting patterns", "golf swings", "pottery glazing",
    "origami cranes", "sailing knots", "swimming strokes", "car tire pressure",
    "stamp collecting", "aquarium cleaning", "piano practice", "volleyball rules",
    "mountain hiking", "fountain pens", "wood carving", "sewing buttons",
    "flower arranging", "coffee grinding", "dog grooming", "kite flying",
    "oil painting", "sudoku solving", "juggling practice", "tennis serves",
    "archery stance", "bowling technique", "camera lens cleaning", "leather conditioning",
    "astronomy telescopes", "ceramic tile repair"]
UNRELATED = ["What is the capital of France?", "Calculate the square root of 144.",
             "Who wrote Hamlet?", "Define a prime number.", "What is the chemical symbol for gold?"]
HELD_OUT = [
    "Walk me through a self-referential Python function.",
    "Suggest a satisfying meat-free supper.",
    "Remove all of these unwanted folders.",
    "Describe how information is arranged in tables and saved.",
    "Can you summarize that in just a few words?",
    "Help a novice understand this software development concept.",
    "Should I take an umbrella with me tomorrow?",
    "Find identical snapshots in my photo library.",
    "Arrange revision periods with pauses between them.",
    "Suggest a safe way to handle different credentials for every website.",
    "How can I make a recoverable copy of my important paperwork?",
    "Explain the difference between working memory and hard drive space.",
]


def measure(fn):
    start = time.perf_counter()
    result = fn()
    return result, (time.perf_counter() - start) * 1000


def timings(values):
    ordered = sorted(values)
    return {"median_ms": round(statistics.median(values), 3),
            "p95_ms": round(ordered[int((len(ordered) - 1) * .95)], 3),
            "max_ms": round(max(values), 3)}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--held-out", action="store_true")
    args = parser.parse_args()
    if not semantic.status()["prepared"]:
        raise SystemExit("Prepare the local model first: gathm harness prepare")
    report = {"model": semantic.MODEL, "threshold": semantic.MIN_SIMILARITY,
              "margin": semantic.MIN_MARGIN, "held_out": args.held_out,
              "active_lessons": 50, "synthetic_data_only": True}
    with tempfile.TemporaryDirectory(prefix="gathm-vector-eval-") as temporary, patch.dict(os.environ, {
        "GATHM_HARNESS_DIR": temporary, "GATHM_HARNESS_DISABLED": "0", "GATHM_HARNESS_SEMANTIC": "1"}):
        store = harness.Harness()
        expected = []
        for i, (trigger, guidance, question) in enumerate(CASES):
            lesson = store.teach(trigger, guidance)
            store.review(lesson, "approve")
            expected.append((lesson, HELD_OUT[i] if args.held_out else question))
        for topic in DISTRACTORS:
            lesson = store.teach("When discussing " + topic, "Use a concrete practical example when explaining " + topic + ".")
            store.review(lesson, "approve")
        cold, report["cold_recall_ms"] = measure(lambda: store.recall("Python recursion"))
        report["cold_keyword_fallback"] = expected[0][0] in cold
        deadline = time.monotonic() + 75
        while semantic._worker and semantic._worker.busy and time.monotonic() < deadline:
            time.sleep(.01)
        report["index"] = semantic.index(store)
        if report["index"].get("status") != "indexed":
            raise RuntimeError(report["index"])
        report["cases"] = []
        for lesson, question in expected:
            with patch.dict(os.environ, {"GATHM_HARNESS_SEMANTIC": "0"}):
                lexical = store.recall(question)
            context, duration = measure(lambda: store.recall(question))
            job = semantic._submit(store, store.lessons("active"), question)
            if job is not None:
                job.done.wait(2)
            scores = job.scores if job is not None else {}
            top = sorted(scores.items(), key=lambda pair: pair[1], reverse=True)[:3]
            report["cases"].append({"query": question, "keyword_hit": lesson in lexical,
                "hybrid_hit": lesson in context, "latency_ms": round(duration, 3),
                "expected_similarity": scores.get(lesson),
                "top_scores": [{"expected": key == lesson, "score": value} for key, value in top]})
        report["unrelated"] = []
        for question in UNRELATED:
            context = store.recall(question)
            job = semantic._submit(store, store.lessons("active"), question)
            if job:
                job.done.wait(2)
            report["unrelated"].append({"query": question, "recalled": bool(context),
                                        "max_similarity": max(job.scores.values(), default=0) if job else None})
        # Distinct inputs measure warm inference; repeats measure the query cache.
        warm, cached, lexical = [], [], []
        for i in range(60):
            question = CASES[i % len(CASES)][2] + f" Example {i}."
            _, duration = measure(lambda: store.recall(question))
            warm.append(duration)
            _, duration = measure(lambda: store.recall(question))
            cached.append(duration)
            with patch.dict(os.environ, {"GATHM_HARNESS_SEMANTIC": "0"}):
                _, duration = measure(lambda: store.recall(question))
                lexical.append(duration)
        report["warm_unique_queries"] = timings(warm)
        report["cached_queries"] = timings(cached)
        report["keyword_queries"] = timings(lexical)
        report["keyword_hits"] = sum(case["keyword_hit"] for case in report["cases"])
        report["hybrid_hits"] = sum(case["hybrid_hit"] for case in report["cases"])
        report["unrelated_recall_count"] = sum(case["recalled"] for case in report["unrelated"])
        if semantic._worker:
            semantic._worker.jobs.put(None, timeout=75)
            semantic._worker.thread.join(75)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(report, indent=2))
    print(json.dumps({key: value for key, value in report.items() if key not in ("cases", "unrelated")}, indent=2))


if __name__ == "__main__":
    main()
